// Generated from the pinned tcode_control contract in control_contract.rs.
use crate::control_contract::*;
use serde_json::{Value, json};

fn start_thread_schema() -> Value {
    let mut schema = serde_json::to_value(schemars::schema_for!(StartThreadParams))
        .expect("StartThreadParams schema serializes");
    if let Some(props) = schema.get_mut("properties").and_then(Value::as_object_mut) {
        props.insert("access_mode".into(), json!({"type":"string","enum":["supervised","auto-accept-edits","auto","full-access"],"description":"Explicit runtime access mode; requires settings_write. If omitted, uses configured defaults."}));
        if let Some(options) = props.get_mut("options") {
            options["description"] = json!("Provider options such as reasoningEffort. Options governing approvals additionally require settings_write.");
        }
        props.insert(
            "role".to_owned(),
            json!({
                "type": ["string", "null"],
                "description": "Optional role id from Settings -> Orchestration (e.g. planner, implementer, reviewer, researcher, verifier). When provided, applies its guidelines to the first message and resolves its configured routing. Pinned provider, profile, model and reasoningEffort cannot be overridden: conflicting arguments return control.role_routing_conflict. Omit role for a distinct explicitly routed task. Use subagent=true for managed delegation."
            }),
        );
        props.insert(
            "todo_id".to_owned(),
            json!({
                "type": ["string", "null"],
                "description": "Optional SRC workbench todo_id to bind this delegated subthread to (updates executor, status and report_back automatically)."
            }),
        );
        props.insert(
            "delegation_profile".to_owned(),
            json!({
                "type": ["string", "null"],
                "enum": ["readonly_analysis", "scoped_execution", null],
                "description": "Optional SRC delegation profile for SRC subthreads (defaults to readonly_analysis; use scoped_execution only when explicitly delegating bounded active execution)."
            }),
        );
        props.insert(
            "allowed_refs".to_owned(),
            json!({
                "type": ["array", "null"],
                "items": {
                    "type": "object",
                    "properties": {
                        "kind": { "type": "string" },
                        "id": { "type": "string" }
                    },
                    "required": ["kind", "id"]
                },
                "description": "Optional whitelist of SRC object refs ({kind, id}) this delegated subthread may inspect in detail."
            }),
        );
        props.insert(
            "allowed_tools".to_owned(),
            json!({
                "type": ["array", "null"],
                "items": { "type": "string" },
                "description": "Optional tool name whitelist narrowing the delegated SRC subthread's MCP tool surface."
            }),
        );
        if let Some(proj) = props.get_mut("project_id") {
            proj["type"] = json!(["string", "null"]);
        }
    }
    if let Some(required) = schema.get_mut("required").and_then(Value::as_array_mut) {
        required.retain(|item| !matches!(item.as_str(), Some("provider" | "project_id")));
    }
    schema
}

fn patch_settings_schema() -> Value {
    let mut schema = serde_json::to_value(schemars::schema_for!(PatchSettingsParams))
        .expect("PatchSettingsParams schema serializes");
    schema["properties"]["patch"]["description"] = json!("{type,content,mode?}: orchestration (full roster for default conversation or mode='src' / content={mode,profile}), ui (UI preference patch), control, control_policy, thread_grant ({thread_id,grant}; read via muteki_get_thread), browser, agent_version_policy, competition_advisor, runner_listener, host_credential, access or system_update (settings-page JSON). Read first using muteki_get_ui_settings(section=target). Existing typed display/settlement patches also work. Requires settings_write.");
    schema
}

pub fn catalog() -> Vec<Value> {
    vec![
        json!({"name":"muteki_list_projects","description":"List the projects in scope: id, name, root, whether it is the quick-chat scratch project, and thread counts by state (active, settled, archived). Reads only.","target_kind":"query","operation":"control.list_projects","aggregate":"thread","input_schema":schemars::schema_for!(ListProjectsParams)}),
        json!({"name":"muteki_list_threads","description":"List threads in scope with id, title, project, provider and model, state, settled_at, archived_at, pinned, follow-up, last_activity_at, last_human_message_at, parent and linked pull requests; include_worktree adds cwd, worktree kind and live dirty state. Paged by cursor. Reads only.","target_kind":"query","operation":"control.list_threads","aggregate":"thread","input_schema":schemars::schema_for!(ListThreadsParams)}),
        json!({"name":"muteki_get_thread","description":"One thread in full: everything list_threads shows except the live dirty state of its worktree, plus the settlement explanation (whether automatic settlement would apply and, if not, which override, toggle, pin, child status, blocker or project override prevents it), queue counts by origin, pending approval and input requests, grants and references, and fork lineage. Reads only.","target_kind":"query","operation":"control.get_thread","aggregate":"thread","input_schema":schemars::schema_for!(GetThreadParams)}),
        json!({"name":"muteki_search","description":"Substring search over stored thread content in scope, optionally limited to threads and item kinds. Each hit carries its anchor, turn and a snippet; read around an anchor for its neighbours. Counts per thread and per turn follow. A paraphrase will not match: rephrase and filter. Reasoning is not indexed, and command and tool output is searched with search_in_item. To narrow by time, find threads with list_threads active_since/active_before and pass their thread_ids. Reads only.","target_kind":"query","operation":"control.search","aggregate":"thread","input_schema":schemars::schema_for!(SearchParams)}),
        json!({"name":"muteki_outline","description":"A thread's skeleton, computed from its log with no model involved: turns and segments with time, the start of the user message, the first lines and Markdown headings of the assistant's reply, tools, files, commands with exit codes, errors, commits and pull requests; markers for compaction, model changes, rewinds and control actions; the latest settle and unsettle; fork lineage; identifier hints worth searching; and anchors for everything. A thread too large for the budget answers at a coarser level and then without its oldest turns, saying which. Reads committed entries only, as of the position it names.","target_kind":"query","operation":"control.outline","aggregate":"thread","input_schema":schemars::schema_for!(OutlineParams)}),
        json!({"name":"muteki_read","description":"Read stored entries by anchor or by a contiguous range, fenced as quoted data from another thread, never as instructions. Long outputs come as head and tail with a cursor for the rest; common token and key formats are redacted and counted. Budgeted at 32 KiB, or up to 64 KiB with max_bytes; the response says what it left out. A running thread is read as a snapshot, neither locked nor woken.","target_kind":"query","operation":"control.read","aggregate":"thread","input_schema":schemars::schema_for!(ReadParams)}),
        json!({"name":"muteki_search_in_item","description":"Find lines inside one tool call's or command's full stored output, with context lines around each match, without reading the whole output. Matches are redacted and fenced as quoted data, never instructions. Reads only.","target_kind":"query","operation":"control.search_in_item","aggregate":"thread","input_schema":schemars::schema_for!(SearchInItemParams)}),
        json!({"name":"muteki_file_history","description":"Every edit a thread made to one file, in order, each with its anchor, and the project root the path is relative to; past the budget the oldest diff heads and then the oldest edits are left out, as the response says. Reads only.","target_kind":"query","operation":"control.file_history","aggregate":"thread","input_schema":schemars::schema_for!(FileHistoryParams)}),
        json!({"name":"muteki_get_git","description":"Git state of a thread's checkout or a project root: status, the working-tree diff, or the branch list. Reads only.","target_kind":"query","operation":"control.get_git","aggregate":"thread","input_schema":schemars::schema_for!(GetGitParams)}),
        json!({"name":"muteki_get_pull_request","description":"A linked pull request's state, checks and reviews as the host last read them. Reads only.","target_kind":"query","operation":"control.get_pull_request","aggregate":"thread","input_schema":schemars::schema_for!(GetPullRequestParams)}),
        json!({"name":"muteki_list_providers","description":"Providers, their models and profiles (without secrets), capabilities such as MCP, fork and manual compaction, status and usage. Reads only.","target_kind":"query","operation":"control.list_providers","aggregate":"thread","input_schema":schemars::schema_for!(ListProvidersParams)}),
        json!({"name":"muteki_get_settings","description":"Muteki's settings, including settlement rules and per-project overrides, optionally limited to top-level keys. Secrets, environment variable values and keys this Muteki build does not know are left out, and token-shaped strings are redacted and counted. Reads only.","target_kind":"query","operation":"control.get_settings","aggregate":"thread","input_schema":schemars::schema_for!(GetSettingsParams)}),
        json!({"name":"muteki_read_terminal","description":"A snapshot of one terminal's screen. Reads only.","target_kind":"query","operation":"control.read_terminal","aggregate":"thread","input_schema":schemars::schema_for!(ReadTerminalParams)}),
        json!({"name":"muteki_review_candidates","description":"The facts a conversation review needs for the threads in scope: pending input and approvals, unsettled older threads, threads held active by a manual unsettle, dirty worktrees that cannot be tied to one thread, settlement explanations and pull request state. Changes nothing; group and judge the evidence yourself, then record_review.","target_kind":"query","operation":"control.review_candidates","aggregate":"thread","input_schema":schemars::schema_for!(ReviewCandidatesParams)}),
        json!({"name":"muteki_update_threads","description":"Change thread lifecycle and metadata in a batch: settle, unsettle, archive, unarchive, pin, unpin, rename, mark_read, mark_unread, follow_up, park and keep. One result per change in input order (applied, would_apply, skipped or failed, with the reason); dry_run previews without changing anything, and expect skips a thread that changed since you looked. A busy thread refuses settle as busy. Settle stops the provider, ends the thread's pull request watches, drops its non-human queued messages, ends the shells of its idle terminals (their output stays readable), unpins it, and closes pending non-blocking input unanswered; the result lists the side effects that actually happened. Unsettle restores none of these: the thread merely becomes Active again, held out of automatic settlement by an override. Archive hides the thread until unarchived.","target_kind":"query","operation":"control.update_threads","aggregate":"thread","input_schema":schemars::schema_for!(UpdateThreadsParams)}),
        json!({"name":"muteki_record_review","description":"Store a conversation review: the grouped items with their evidence and your coverage statement. Changes no thread state; the user acts on it in Muteki.","target_kind":"query","operation":"control.record_review","aggregate":"thread","input_schema":schemars::schema_for!(RecordReviewParams)}),
        json!({"name":"muteki_settle_self","description":"Arrange for this thread, and only this thread, to settle itself: at the end of your current turn, or when a named pull request merges or closes. Requires the user's consent, quoted verbatim in consent_quote from a message the user sent in this thread (case and spacing aside); a quote the user never said here is refused. The user can revoke it from the thread's title menu, and any new message from the user withdraws it. Settle stops the provider, ends the thread's pull request watches, drops its non-human queued messages, ends the shells of its idle terminals (their output stays readable), unpins it, and closes pending non-blocking input unanswered. Never fires mid-turn.","target_kind":"query","operation":"control.settle_self","aggregate":"thread","input_schema":schemars::schema_for!(SettleSelfParams)}),
        json!({"name":"muteki_start_thread","description":"Start a new thread with a first message, recorded as started by this thread and never blocking you; any provider muteki_list_providers lists, with its actual profile and model IDs. By default it is an ordinary thread in a project's checkout, not a child of this thread, running with the project's default permission mode. With subagent: true it is this thread's subagent instead: listed in this thread's Subagents view rather than on its own, running with the permission Settings → Control subagent approvals chooses, optionally in a dedicated worktree. Use role to resolve configured routing and append role guidelines; pinned provider/profile/model/effort conflicts are rejected. A subagent sees nothing of your transcript, so make its first message self-contained; Muteki appends the report contract to it. You receive its report_result as a message when its turn ends (if it never reports, Muteki reminds it once, then sends you its final message as a labelled fallback; a provider without MCP gets neither the contract nor the reminder, so you receive its final message), a failure if its turn fails, nothing if the user interrupts it, and its approval requests and questions as they come; settle it with muteki_update_threads once you accept its result, or cancel it with muteki_control_thread to stop it undelivered. The user's standing draft is never touched. request_id is stored on the thread, so a retry after a failure or restart returns the same thread. The message is sent as from this thread (origin agent) and never counts as the user's activity. options set provider options such as reasoningEffort; options governing approvals additionally require settings_write. cwd is relative to the project root and must stay inside it. Attachments must already be in the attachments folder of a thread in your scope, such as images the user attached here; other paths are refused.","target_kind":"query","operation":"control.start_thread","aggregate":"thread","input_schema":start_thread_schema()}),
        json!({"name":"muteki_send_message","description":"Send a message to threads: queue it after the running turn, steer it into the running turn (queued when none is running), or schedule it for a unix time. Sent as from this thread (origin agent): it wakes a settled thread but never counts as the user's activity. To your own subagent each message you queue or steer opens a new report it owes you, superseding one it has not delivered yet; a scheduled one does not. Attachments must already be in the attachments folder of a thread in your scope; other paths are refused. One result per thread. A request_id retry returns the first answer while the host keeps running; that memory does not survive a host restart.","target_kind":"query","operation":"control.send_message","aggregate":"thread","input_schema":schemars::schema_for!(SendMessageParams)}),
        json!({"name":"muteki_control_thread","description":"Drive a thread's run in a batch: interrupt, retry a turn, compact context, set the model within the thread's own provider and profile or a provider option (takes effect from the next turn), fork, steer a queued message, drop a queued message, or cancel your own subagent: stopped with its result kept but undelivered, it no longer keeps you waiting, and a message reopens it. Use {set_runtime:{adapter_id,instance_id,credential_id,model,effort,service_tier,interaction_mode,access_mode,options}} to update runtime fields (requires settings_write; omitted fields stay unchanged). Options governing approvals additionally require settings_write. Dropping a queued human message needs history_edit. One result per change in input order. A request_id retry returns the first answer while the host keeps running; that memory does not survive a host restart.","target_kind":"query","operation":"control.control_thread","aggregate":"thread","input_schema":schemars::schema_for!(ControlThreadParams)}),
        json!({"name":"muteki_pull_request","description":"Link, unlink, watch, unwatch or refresh a pull request for a thread; with pr_write also comment, reply in a review comment thread, or resolve one on the host. A watch wakes the thread when checks fail or pass, someone else comments or reviews, the branch conflicts, or the pull request merges or closes; it ends when the thread settles or is archived.","target_kind":"query","operation":"control.pull_request","aggregate":"thread","input_schema":schemars::schema_for!(PullRequestParams)}),
        json!({"name":"muteki_git","description":"Local git in a thread's checkout: checkout_branch (refused while a turn runs or the tree is dirty) and commit. With git_remote also push, pull, commit_push, publish_branch and merge_worktree, which reach the remote or rewrite the project checkout.","target_kind":"query","operation":"control.git","aggregate":"thread","input_schema":schemars::schema_for!(GitParams)}),
        json!({"name":"muteki_create_project","description":"Register a project on the host at an existing absolute directory, or return the project already registered at that directory. The project is the host's, visible to every client of this host, not only to this thread.","target_kind":"query","operation":"control.create_project","aggregate":"thread","input_schema":schemars::schema_for!(CreateProjectParams)}),
        json!({"name":"muteki_move_thread","description":"Move a thread into another project in your grant's scope, continuing its conversation in that project's root or in cwd inside it. A provider whose native session can move goes along with it; any other restarts in the new directory, and its first turn there receives a handoff of the conversation so far, shown to the user; the Muteki transcript stays as it is. This thread may also move itself into a project outside that scope while the project has no threads yet, such as one you just created. Threads with a dedicated worktree cannot be moved; a busy thread other than this one is refused as busy; this thread moves at once, and its provider follows when your current turn ends. Typical flow for starting something new: clone or mkdir it with your shell, create_project on that directory, then move_thread on your own thread id.","target_kind":"query","operation":"control.move_thread","aggregate":"thread","input_schema":schemars::schema_for!(MoveThreadParams)}),
        json!({"name":"muteki_notify_when","description":"Register a wake on other threads' events (idle, turn_completed, needs_input, needs_approval, settled, pr_changed) instead of polling. When one fires you receive a message \"[control] thread <id> (\"<title>\") <event>: <detail>\" as from an agent; the detail of turn_completed and idle names the turn (numbered as outline numbers them) and quotes the message that started it. idle means the thread has no work left, and pr_changed fires for pull requests the watched thread itself watches. once removes the watch after it fires. Returns the watch id for cancel_notify; a thread that is unknown or outside your grant is listed under skipped with the reason, and no watch is stored when every thread is skipped. The watch is stored on this thread and survives a restart.","target_kind":"query","operation":"control.notify_when","aggregate":"thread","input_schema":schemars::schema_for!(NotifyWhenParams)}),
        json!({"name":"muteki_cancel_notify","description":"Remove watches notify_when registered, by id.","target_kind":"query","operation":"control.cancel_notify","aggregate":"thread","input_schema":schemars::schema_for!(CancelNotifyParams)}),
        json!({"name":"muteki_reference","description":"Reference another thread within your observe scope so its stored log stays readable to this thread through outline, read, search_in_item and file_history. For targeted recovery of specific facts, not for reading whole transcripts; the reference is shown to the user as a chip on this thread, and a reference across a project or provider boundary is announced to the user when you make it. Forks of this thread inherit it.","target_kind":"query","operation":"control.reference","aggregate":"thread","input_schema":schemars::schema_for!(ReferenceParams)}),
        json!({"name":"muteki_respond_input","description":"Answer another thread's pending user-input request in the user's place: for your own subagent, from your brief and the user's instructions; for any other thread only with the privileged category answer_input. answers has one entry per question, keyed by question id: a string (an option label or free text) for a single-choice question, an array of strings for a multi_select one. Every use is logged in both threads. Tool-call approvals are answered with respond_approval, never here.","target_kind":"query","operation":"control.respond_input","aggregate":"thread","input_schema":schemars::schema_for!(RespondInputParams)}),
        json!({"name":"muteki_respond_approval","description":"Answer a pending tool-call approval of your own subagent with an exact native option id from its approval message, or cancel: true; never both. Allowed only while Settings → Control subagent approvals makes you the approver (any mode but manual); reject anything outside the scope you gave it. Approvals of any other thread are the user's and are refused. Every use is logged in both threads.","target_kind":"query","operation":"control.respond_approval","aggregate":"thread","input_schema":schemars::schema_for!(RespondApprovalParams)}),
        json!({"name":"muteki_report_result","description":"Send your complete final report to the thread that started you as its subagent. It sees nothing of your turns, wake-ups, Monitor or background work: only this call reaches it, delivered when your current turn ends. Make the report self-contained: your reasoning, recommendations, disagreements and open questions for a discussion; files changed and commands actually run with their outcomes for execution; the evidence for your conclusions in either case. Call it once when the work is complete, before ending your turn; calling again replaces the previous report (last call wins). Only if this call fails, write the same complete report as your final message instead: it is sent back as the fallback.","target_kind":"query","operation":"control.report_result","aggregate":"thread","input_schema":schemars::schema_for!(ReportResultParams)}),
        json!({"name":"muteki_terminal","description":"Open a terminal in a thread's panel, type into one, or close one (privileged: terminal). Input reaches a live shell on the host; every use is logged.","target_kind":"query","operation":"control.terminal","aggregate":"thread","input_schema":schemars::schema_for!(TerminalParams)}),
        json!({"name":"muteki_delete_threads","description":"Delete threads and every thread under them (privileged: delete). Delete is permanent and leaves no tombstone: the log, attachments and metadata are gone and nothing can be restored. remove_worktree also deletes each thread's dedicated worktree unless another thread shares it; dry_run reports what would go and deletes nothing. One result per thread.","target_kind":"query","operation":"control.delete_threads","aggregate":"thread","input_schema":schemars::schema_for!(DeleteThreadsParams)}),
        json!({"name":"muteki_rewind","description":"Rewind a thread to an earlier turn through its provider (privileged: history_edit). files restores the files the provider tracked; conversation cuts what came after the turn from the conversation the provider sees, while the stored log keeps it appended. Only the scopes the provider offers for that turn, and only when its rewind can start. Answers once the provider has: completed, partial (what failed) or failed, with the provider's reason.","target_kind":"query","operation":"control.rewind","aggregate":"thread","input_schema":schemars::schema_for!(RewindParams)}),
        json!({"name":"muteki_patch_settings","description":"Apply a settings patch (requires settings_write). Use patch={type,content,mode?}. type=orchestration saves the full role roster (optionally scoped by mode='conversation'|'src'; pass profile=null to revert 'src' to inherit); type=ui merges UI preference keys; type=control updates enabled/default_grant/project_overrides/project_id/project_grant/subagent_policy/orchestration/orchestration_mode/orchestration_overrides; type=control_policy updates settlement and source_control settings. Also supports browser, agent_version_policy, competition_advisor, runner_listener and host_credential with their settings-page JSON bodies. Read current values first with muteki_get_settings or muteki_get_ui_settings(section=target). Existing typed display and settlement patches remain supported.","target_kind":"query","operation":"control.patch_settings","aggregate":"thread","input_schema":patch_settings_schema()}),
        json!({"name":"muteki_request_grant","description":"Ask the user for a wider grant: a scope, tiers and privileged categories, with your reason. Only asks: the user approves or declines in Muteki's UI, never in chat, and you receive a message \"[control] grant approved: …\" or \"[control] grant declined: …\" when they answer. An approved grant is recorded on this thread and visible to the user. A wider scope or a newly allowed category applies at once to the tools you already have; tools the new grant adds appear only when your provider next starts a session, until then they are not in your tool list. With nothing granted, this is the only tool you have, besides report_result for a subagent.","target_kind":"query","operation":"control.request_grant","aggregate":"thread","input_schema":schemars::schema_for!(RequestGrantParams)}),
    ]
}
